/**
 * Auto-fold end-to-end benchmark.
 *
 * Starts the built billion-context proxy with a config generated by the
 * unified control plane (`compression.mode = "autofold"`), then sends one
 * 36-pair Anthropic request. The external summary service is a local mock, so
 * this measures the plumbing, the injected surface and the fold, not a real
 * summary model's quality or price.
 *
 *   node tools/bench-autofold.mjs [--json docs/bench/autofold.json]
 */
import { spawn } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import http from "node:http";
import net from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { defaultConfig, ensureBillionConfig, getEnginePaths } from "@hypercontext/core";

const repoRoot = join(import.meta.dirname, "..");
const pairs = Number(process.env.AUTOFOLD_PAIRS ?? 36);
const targetTokens = Number(process.env.AUTOFOLD_TARGET ?? 8192);
const home = mkdtempSync(join(tmpdir(), "hctx-autofold-"));
const sessionsDir = join(home, "sessions");
mkdirSync(sessionsDir, { recursive: true });
process.env.HYPERCONTEXT_HOME = home;

const proxyPort = await freePort();
const main = await startMainUpstream();
const summary = await startSummaryUpstream();

const config = defaultConfig();
config.compression.mode = "autofold";
config.compression.summary = {
  baseUrl: summary.url,
  api: "openai",
  apiKeyEnv: "E2E_SUM_KEY",
  model: "mock-summary",
  autoFoldTargetTokens: targetTokens,
  concurrency: 8,
};
const generated = ensureBillionConfig(config);

const proxy = spawn(process.execPath, [getEnginePaths().billionContext.distEntry, "start", "--port", String(proxyPort), "--host", "127.0.0.1"], {
  cwd: repoRoot,
  env: {
    ...process.env,
    BILI_CONFIG_FILE: generated.file,
    BILI_SESSIONS_DIR: sessionsDir,
    ACP_UPSTREAM: main.url,
    ACP_MODEL_CONTEXT_LIMIT: "50000",
    E2E_SUM_KEY: "bench-key",
    XDG_STATE_HOME: join(home, "state"),
    XDG_CACHE_HOME: join(home, "cache"),
  },
  stdio: ["ignore", "pipe", "pipe"],
});
let proxyLog = "";
proxy.stdout.on("data", (chunk) => { proxyLog += chunk.toString(); });
proxy.stderr.on("data", (chunk) => { proxyLog += chunk.toString(); });

try {
  const origin = `http://127.0.0.1:${proxyPort}`;
  if (!(await waitHealthy(origin, 30_000))) {
    throw new Error(`proxy did not become healthy\n${proxyLog.slice(-4000)}`);
  }

  const messages = bigConversation(pairs);
  const response = await fetch(`${origin}/v1/messages`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": "bench",
      "anthropic-version": "2023-06-01",
      "x-acp-session": `autofold-${Date.now()}`,
    },
    body: JSON.stringify({ model: "test-model", max_tokens: 1024, stream: true, messages }),
  });
  const responseText = await response.text();
  await new Promise((resolve) => setTimeout(resolve, 300));

  const forwarded = main.bodies.at(-1) ?? {};
  const report = {
    status: response.status,
    summaryCalls: summary.calls.length,
    summaryInputBytes: summary.calls.reduce((total, size) => total + size, 0),
    originalMessages: messages.length,
    forwardedMessages: Array.isArray(forwarded.messages) ? forwarded.messages.length : null,
    systemBytes: Buffer.byteLength(JSON.stringify(forwarded.system ?? ""), "utf8"),
    toolsBytes: Buffer.byteLength(JSON.stringify(forwarded.tools ?? []), "utf8"),
    responseBytes: Buffer.byteLength(responseText, "utf8"),
  };

  const jsonFlag = process.argv.indexOf("--json");
  if (jsonFlag >= 0) {
    const out = process.argv[jsonFlag + 1];
    if (!out) throw new Error("--json requires a path");
    writeFileSync(out, `${JSON.stringify(report, null, 2)}\n`);
  }
  console.log(JSON.stringify(report));
} finally {
  if (proxy.exitCode === null) {
    proxy.kill();
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  main.server.close();
  summary.server.close();
  rmSync(home, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
}

function freePort() {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.listen(0, "127.0.0.1", () => {
      const port = server.address().port;
      server.close(() => resolve(port));
    });
  });
}

function bigConversation(pairs) {
  const filler = "0123456789abcdef".repeat(280);
  const messages = [];
  for (let i = 0; i < pairs; i++) {
    messages.push({ role: "user", content: [{ type: "text", text: `doc chunk ${i}: ${filler}` }] });
    messages.push({ role: "assistant", content: [{ type: "text", text: `ack ${i}` }] });
  }
  messages.push({ role: "user", content: [{ type: "text", text: "final question" }] });
  return messages;
}

function startMainUpstream() {
  return new Promise((resolve) => {
    const bodies = [];
    const server = http.createServer((req, res) => {
      const chunks = [];
      req.on("data", (chunk) => chunks.push(chunk));
      req.on("end", () => {
        try {
          bodies.push(JSON.parse(Buffer.concat(chunks).toString("utf8")));
        } catch {
          // keep the byte counter meaningful even for a malformed request
        }
        res.writeHead(200, { "content-type": "text/event-stream" });
        const billed = Buffer.concat(chunks).toString("utf8").length > 100_000 ? 42_000 : 1_000;
        res.write(`event: message_start\ndata: {"type":"message_start","message":{"id":"m1","usage":{"input_tokens":${billed}}}}\n\n`);
        res.write('event: message_delta\ndata: {"type":"message_delta","delta":{"stop_reason":"end_turn"},"usage":{"output_tokens":5}}\n\n');
        res.write('event: message_stop\ndata: {"type":"message_stop"}\n\n');
        res.end();
      });
    });
    server.listen(0, "127.0.0.1", () => resolve({ server, url: `http://127.0.0.1:${server.address().port}`, bodies }));
  });
}

function startSummaryUpstream() {
  return new Promise((resolve) => {
    const calls = [];
    const server = http.createServer((req, res) => {
      const chunks = [];
      req.on("data", (chunk) => chunks.push(chunk));
      req.on("end", () => {
        calls.push(Buffer.byteLength(Buffer.concat(chunks).toString("utf8")));
        const summary = "SUMMARY: retained the wifi, ups and gpu facts. "
          + "The conversation covered installation, driver setup, power planning, and troubleshooting. ".repeat(30);
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify({ choices: [{ message: { content: summary }, finish_reason: "stop" }] }));
      });
    });
    server.listen(0, "127.0.0.1", () => resolve({ server, url: `http://127.0.0.1:${server.address().port}`, calls }));
  });
}

function waitHealthy(origin, timeoutMs) {
  return new Promise((resolve) => {
    const deadline = Date.now() + timeoutMs;
    const tick = async () => {
      try {
        const response = await fetch(`${origin}/__bili/health`, { signal: AbortSignal.timeout(1000) });
        if (response.ok) return resolve(true);
      } catch {
        // proxy is still starting
      }
      if (Date.now() >= deadline) return resolve(false);
      setTimeout(tick, 300);
    };
    tick();
  });
}
